def is_stale():
    """True if TOOL_MASTER.yaml has changed since this index was compiled."""
    import hashlib as _h
    import os as _o
    if not _o.path.isfile(MASTER_PATH):
        return True
    with open(MASTER_PATH, "rb") as fh:
        return _h.sha256(fh.read()).hexdigest() != MASTER_SHA256
